import{_ as e,o as l,c as r,a2 as t}from"./chunks/framework.CdvW4CUT.js";const f=JSON.parse('{"title":"遊玩規定  (2022-01-02)","description":"","frontmatter":{},"headers":[],"relativePath":"rule/history/20220102/index.md","filePath":"rule/history/20220102.md"}'),i={name:"rule/history/20220102/index.md"};function o(h,a,n,u,s,d){return l(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="遊玩規定-2022-01-02" tabindex="-1">遊玩規定 (2022-01-02) <a class="header-anchor" href="#遊玩規定-2022-01-02" aria-label="Permalink to &quot;遊玩規定  (2022-01-02)&quot;">​</a></h1><h2 id="伺服規定" tabindex="-1">伺服規定 <a class="header-anchor" href="#伺服規定" aria-label="Permalink to &quot;伺服規定&quot;">​</a></h2><h4 id="當您加入伺服器遊玩-即視為您同意並遵守此規定" tabindex="-1">當您加入伺服器遊玩，即視為您同意並遵守此規定 <a class="header-anchor" href="#當您加入伺服器遊玩-即視為您同意並遵守此規定" aria-label="Permalink to &quot;當您加入伺服器遊玩，即視為您同意並遵守此規定&quot;">​</a></h4><ul><li>最後更新時間 : 2022/01/02</li></ul><h3 id="任何公頻發言-請遵守-公頻規範" tabindex="-1">任何公頻發言，請遵守 <a href="/rule/history/chat/"><strong>公頻規範</strong></a> <a class="header-anchor" href="#任何公頻發言-請遵守-公頻規範" aria-label="Permalink to &quot;任何公頻發言，請遵守 [**公頻規範**](./chat.md)&quot;">​</a></h3><ul><li>此為獨立頁面超連結，請點擊上方連結查看</li></ul><h3 id="請勿影響其他玩家遊玩" tabindex="-1">請勿影響其他玩家遊玩 <a class="header-anchor" href="#請勿影響其他玩家遊玩" aria-label="Permalink to &quot;請勿影響其他玩家遊玩&quot;">​</a></h3><ul><li><strong>影響他人</strong>的行為係指： <ul><li>破壞、偷竊、騷擾、詐欺、誤導、盜畫、影響效能...</li></ul></li><li>基本上，在路上看到人造建築與箱子不要任意去亂碰</li></ul><h3 id="嚴禁使用外掛功能-遊戲bug" tabindex="-1">嚴禁使用外掛功能/遊戲BUG <a class="header-anchor" href="#嚴禁使用外掛功能-遊戲bug" aria-label="Permalink to &quot;嚴禁使用外掛功能/遊戲BUG&quot;">​</a></h3><ul><li><a href="/rule/history/modrule/">容許與禁止的詳細說明</a></li></ul><h3 id="請勿開分身或使用vpn遊玩" tabindex="-1">請勿開分身或使用VPN遊玩 <a class="header-anchor" href="#請勿開分身或使用vpn遊玩" aria-label="Permalink to &quot;請勿開分身或使用VPN遊玩&quot;">​</a></h3><ul><li>若有這類需求，請務必<strong>主動</strong>利用<a href="/rule/contact/">客服</a>向伺服人員詢問或提出申請</li><li>違反本項規定將依照伺服人員之認定進行處置</li></ul><h3 id="嚴禁影響伺服運作" tabindex="-1">嚴禁影響伺服運作 <a class="header-anchor" href="#嚴禁影響伺服運作" aria-label="Permalink to &quot;嚴禁影響伺服運作&quot;">​</a></h3><h2 id="備註" tabindex="-1">備註 <a class="header-anchor" href="#備註" aria-label="Permalink to &quot;備註&quot;">​</a></h2><ul><li>伺服處分以帳號與IP為準，請務必保管好個人帳號 <ul><li>切勿外借給任何人，若發生任何狀況須自行承擔責任</li><li>帳號之所有一切行為皆代表您本人之行為，不接受任何因個人因素導致之理由(朋友玩的/家人玩的/帳號被盜...)作為要求解除處分之依據。</li></ul></li><li>若發現有玩家有違反以上規定時，請即時利用<a href="/rule/contact/">客服</a>，切勿知情不報</li><li>若對於規定有任何疑慮或意見，請利用<a href="/rule/contact/">客服</a>主動詢問伺服人員</li></ul>',15)])])}const _=e(i,[["render",o]]);export{f as __pageData,_ as default};
